#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int n;
    ll *bit;
} Fenwick;

void fenwick_init(Fenwick *fw, int n) {
    fw->n = n;
    fw->bit = (ll *)calloc(n + 1, sizeof(ll));
}

void fenwick_add(Fenwick *fw, int idx, ll val) {
    idx++; // 0-indexed to 1-indexed
    while (idx <= fw->n) {
        fw->bit[idx] += val;
        idx += idx & -idx;
    }
}

ll fenwick_sum_prefix(Fenwick *fw, int r) {
    ll s = 0;
    while (r > 0) {
        s += fw->bit[r];
        r -= r & -r;
    }
    return s;
}

ll fenwick_sum_range(Fenwick *fw, int l, int r) {
    return fenwick_sum_prefix(fw, r) - fenwick_sum_prefix(fw, l);
}

int main(void) {
    int N, Q;
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    Fenwick fw;
    fenwick_init(&fw, N);

    for (int i = 0; i < N; i++) {
        ll a;
        scanf("%lld", &a);
        fenwick_add(&fw, i, a);
    }

    for (int i = 0; i < Q; i++) {
        int t, x, y;
        scanf("%d %d %d", &t, &x, &y);
        if (t == 0) {
            fenwick_add(&fw, x, (ll)y);
        } else {
            printf("%lld\n", fenwick_sum_range(&fw, x, y));
        }
    }

    free(fw.bit);
    return 0;
}

