typedef long long ll;

struct BIT {
    int n;
    vector<ll> tree;
    BIT(int n) : n(n), tree(n+1, 0) {}
    void update(int i, ll delta) {
        for (i++; i <= n; i += i & (-i))
            tree[i] += delta;
    }
    ll query(int i) {
        ll s = 0;
        for (i++; i > 0; i -= i & (-i))
            s += tree[i];
        return s;
    }
    ll query(int l, int r) { // [l, r)
        if (l >= r) return 0;
        return query(r-1) - (l > 0 ? query(l-1) : 0);
    }
};

