public class Main {
    // Fenwick Tree / Binary Indexed Tree
    static class Fenwick {
        int n;
        long[] bit;

        Fenwick(int n) {
            this.n = n;
            this.bit = new long[n + 1];
        }

        void add(int idx, long val) {
            idx++; // 1-based
            while (idx <= n) {
                bit[idx] += val;
                idx += idx & -idx;
            }
        }

        long sumPrefix(int idx) {
            long res = 0;
            while (idx > 0) {
                res += bit[idx];
                idx -= idx & -idx;
            }
            return res;
        }

        long sumRange(int l, int r) {
            return sumPrefix(r) - sumPrefix(l);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int N = fs.nextInt();
        int Q = fs.nextInt();

        Fenwick fw = new Fenwick(N);

        for (int i = 0; i < N; i++) {
            long a = fs.nextLong();
            fw.add(i, a);
        }

        for (int i = 0; i < Q; i++) {
            int type = fs.nextInt();
            if (type == 0) {
                int p = fs.nextInt();
                long x = fs.nextLong();
                fw.add(p, x);
            } else {
                int l = fs.nextInt();
                int r = fs.nextInt();
                out.append(fw.sumRange(l, r)).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

