        self.n = n
        self.bit = [0] * (n + 1)

    def update(self, idx, delta):
        i = idx + 1
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def query(self, idx):
        res = 0
        i = idx + 1
        while i > 0:
            res += self.bit[i]
            i -= i & -i
        return res

    def range_sum(self, l, r):
        return self.query(r - 1) - self.query(l - 1)

